pair A, B, C, D, M, N;

A = (0,0);
B = (4,0.5);
C = (5,-3);
D = (-2,-2.5);
M = (A + C)/2;
N = (B + D)/2;

draw(A--B--C--D--cycle);
draw(A--C);
draw(B--D);
draw(M--N);

